using JobTrack.Domain.Entities;

namespace JobTrack.Application.Resumes;

public enum ResumeFileKind
{
    Pdf,
    Docx,
}

/// <summary>Private binary storage for uploaded files. Keys are generated by the server, never taken from clients.</summary>
public interface IFileStorage
{
    Task SaveAsync(string key, Stream content, CancellationToken ct);
    Task<Stream> OpenReadAsync(string key, CancellationToken ct);
    Task DeleteAsync(string key, CancellationToken ct);
}

/// <summary>Extracts plain text from a CV. Throws <see cref="Domain.Common.DomainException"/> for unreadable files.</summary>
public interface IResumeTextExtractor
{
    Task<string> ExtractAsync(Stream content, ResumeFileKind kind, CancellationToken ct);
}

/// <summary>Everything an analyzer needs. Both texts are user-provided and must be treated as untrusted data.</summary>
public sealed record ResumeAnalysisInput(
    string ResumeText,
    string JobTitle,
    string CompanyName,
    string? JobDescription,
    IReadOnlyList<string> RequiredSkills,
    IReadOnlyList<string> PreferredSkills);

public sealed record ResumeAnalysisOutcome(ResumeAnalysisResult Result, string Model, string PromptVersion);

/// <summary>
/// A pluggable analyzer (local heuristics, an LLM provider…). Implementations must return evidence quoted from the
/// inputs only; the caller re-validates every result with <see cref="ResumeAnalysisResultSanitizer"/> before storing it.
/// </summary>
public interface IResumeAnalysisService
{
    /// <summary>Stable identifier stored with each analysis, e.g. "local" or "anthropic".</summary>
    string ProviderId { get; }

    string DisplayName { get; }

    /// <summary>True when the CV text leaves this server (requires explicit user consent).</summary>
    bool IsExternal { get; }

    /// <summary>False when the provider is not configured (e.g. no API key); the rest of the app keeps working.</summary>
    bool IsAvailable { get; }

    /// <summary>Model or algorithm identifier shown to users when available.</summary>
    string? ModelName { get; }

    Task<ResumeAnalysisOutcome> AnalyzeAsync(ResumeAnalysisInput input, CancellationToken ct);
}
